---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Bar chart: Weekly agent runs, split by outcome, with a range switch.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change bar-chart.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './bar-chart.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="bar-chart" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="bcx panel">
  <div class="bcx-h"><div><span class="muted">Agent runs</span><b class="num bcx-v">0</b></div><div class="seg2 bcx-rg" role="group" aria-label="Range"><button aria-pressed="true" data-v="w">Week</button><button aria-pressed="false" data-v="m">Month</button></div></div>
  <div class="bcx-ch"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './bar-chart.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Bar chart ---------- */
.bcx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.bcx-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.bcx-h>div:first-child{display:flex;flex-direction:column;font-size:12.5px}
.bcx-v{font-size:14px;font-weight:500;letter-spacing:-.02em}
.bcx-rg button{font-size:12px;height:26px;padding:0 10px}
.bcx-ch{display:flex;align-items:flex-end;gap:var(--dm-s-2);height:150px;position:relative}
.bcx-b{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;gap:0;position:relative;cursor:default}
.bcx-st{display:flex;flex-direction:column-reverse;gap:2px;border-radius:calc(7px * var(--dm-rk));overflow:hidden;transition:opacity .25s}
.bcx-st i{display:block;height:0;transition:height .7s var(--dm-ease)}
.bcx-st i:nth-child(1){background:var(--dm-c1)}
@media (hover:hover) and (pointer:fine){.bcx-ch:hover .bcx-b:not(:hover) .bcx-st{opacity:.4}}
.bcx-l{font-size:11px;color:var(--dm-muted);text-align:center;margin-top:6px;height:14px}
.bcx-tt{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translate(-50%,4px);padding:6px 9px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-ink);color:var(--dm-on-ink);font-size:11.5px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .2s,transform .25s var(--dm-ease);z-index:2;display:flex;flex-direction:column}
.bcx-tt span{opacity:.75}
@media (hover:hover) and (pointer:fine){.bcx-b:hover .bcx-tt{opacity:1;transform:translate(-50%,0)}}
.bcx-b:first-child .bcx-tt{left:0;transform:translate(0,4px)}@media (hover:hover) and (pointer:fine){.bcx-b:first-child:hover .bcx-tt{transform:none}}
.bcx-b:last-child .bcx-tt{left:auto;right:0;transform:translate(0,4px)}@media (hover:hover) and (pointer:fine){.bcx-b:last-child:hover .bcx-tt{transform:none}}
/* on a phone the bars are too thin for the second and second-last tips to sit centred without passing the edge */
@container (max-width:400px){.bcx-b:nth-child(2) .bcx-tt{left:0;transform:translate(0,4px)}@media (hover:hover) and (pointer:fine){.bcx-b:nth-child(2):hover .bcx-tt{transform:none}}.bcx-b:nth-last-child(2) .bcx-tt{left:auto;right:0;transform:translate(0,4px)}@media (hover:hover) and (pointer:fine){.bcx-b:nth-last-child(2):hover .bcx-tt{transform:none}}}
.bcx-lg{display:flex;gap:14px;font-size:12px;flex-wrap:wrap}
.bcx-lg span{display:flex;align-items:center;gap:6px}
.bcx-lg i{width:8px;height:8px;border-radius:3px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, seg, tween } from '../core/core.js';
DM.def('bar-chart', (r, c) => {
  const D = {
    w:{ l:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], d:[[42,9,2],[51,12,3],[48,8,1],[63,10,4],[57,14,2],[18,3,0],[12,2,1]] },
    m:{ l:['W1','W2','W3','W4','W5','W6','W7'], d:[[180,40,9],[210,44,12],[236,51,8],[262,48,10],[251,39,6],[298,52,7],[321,47,5]] }
  };
  const ch = $('.bcx-ch', r), v = $('.bcx-v', r); let tot = 0;
  ch.innerHTML = D.w.l.map(() => `<div class="bcx-b"><div class="bcx-tt"><b class="num"></b><span></span></div><div class="bcx-st"><i></i></div><div class="bcx-l"></div></div>`).join('');
  const bars = $$('.bcx-b', ch);
  function draw(k){
    const d = D[k], mx = Math.max(...d.d.map(x => x[0] + x[1] + x[2])) * 1.08, H = ch.clientHeight - 22;
    bars.forEach((b, i) => { const x = d.d[i], s = x[0] + x[1] + x[2];
      c.later(i * 45, () => { $('.bcx-st i', b).style.height = Math.max(s ? 3 : 0, s / mx * H) + 'px'; });
      $('.bcx-l', b).textContent = d.l[i]; $('.bcx-tt b', b).textContent = s + ' runs'; $('.bcx-tt span', b).textContent = `${x[0]} shipped, ${x[1]} reviewed, ${x[2]} failed`; });
    const t = d.d.reduce((a, x) => a + x[0] + x[1] + x[2], 0); tween(tot, t, 900, n => { tot = n; v.textContent = Math.round(n).toLocaleString('en-US'); });
  }
  seg($('.bcx-rg', r), draw);
  c.later(280, () => draw('w'));
});
